  res.status(204).send();
});","codeExample2":"// Global error middleware (must be last, 4-arg signature)
app.use((err: Error, _req: Request, res: Response, _next: NextFunction) => {
  console.error(err.stack);
  res.status(500).json({ error: err.message });
});"},{"topic":"React 18 Custom Hook: useFetch with loading/error/refetch","summary":"Pattern: generic useFetch<T>(url, refreshKey) hook using useState + useEffect. Cleanup via cancelled flag prevents state updates after unmount (critical for React 18 StrictMode double-invoke). Refetch is triggered by incrementing a refreshKey counter passed as a dep. Error set from res.ok check before parsing JSON.","source":"https://www.robinwieruch.de/react-hooks-fetch-data/","relevance":"high","codeExample":"// src/hooks/useUsers.ts
import { useState, useEffect } from 'react';
import type { User } from '../types/user';

export function useUsers() {
  const [users, setUsers] = useState<User[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [refreshKey, setRefreshKey] = useState(0);

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    setError(null);
    fetch('/api/users')
      .then(res => { if (!res.ok) throw new Error(`HTTP ${res.status}`); return res.json() as Promise<User[]>; })
      .then(data => { if (!cancelled) { setUsers(data); setLoading(false); } })
      .catch(err => { if (!cancelled) { setError(err.message); setLoading(false); } });
    return () => { cancelled = true; };
  }, [refreshKey]);

  const refresh = () => setRefreshKey(k => k + 1);
  return { users, loading, error, refresh };
}"},{"topic":"React 18 Form State Pattern (no external library)","summary":"Single form state object with computed handleChange using [e.target.name]. Separate submitting + formError states. handleSubmit: preventDefault, set submitting=true, fetch POST/PUT, throw on !res.ok, call onSuccess callback, catch sets formError, finally clears submitting. Inline validation before fetch call.","source":"https://www.robinwieruch.de/react-hooks-fetch-data/","relevance":"high","codeExample":"// src/components/UserForm.tsx
type Props = { onSuccess: () => void; initial?: Partial<User>; userId?: number };

export default function UserForm({ onSuccess, initial, userId }: Props) {
  const [form, setForm] = useState({ name: initial?.name ?? '', email: initial?.email ?? '', avatarUrl: initial?.avatarUrl ?? '' });
  const [submitting, setSubmitting] = useState(false);
  const [formError, setFormError] = useState<string | null>(null);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) =>
    setForm(prev => ({ ...prev, [e.target.name]: e.target.value }));

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!form.name.trim() || !form.email.trim()) { setFormError('Name and email are required'); return; }
    setSubmitting(true);
    setFormError(null);
    try {
      const url = userId ? `/api/users/${userId}` : '/api/users';
      const res = await fetch(url, { method: userId ? 'PUT' : 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(form) });
      if (!res.ok) { const body = await res.json(); throw new Error(body.error ?? `HTTP ${res.status}`); }
      onSuccess();
    } catch (err) {
      setFormError(err instanceof Error ? err.message : 'Unknown error');
    } finally { setSubmitting(false); }
  };
  return ( /* JSX form with Tailwind */ );
}"},{"topic":"Tailwind CSS patterns for loading/error/card UI","summary":"Loading spinner: animate-spin with border-t-transparent. Error banner: bg-red-50 border-l-4 border-red-500 text-red-700. Card: bg-white rounded-xl shadow-sm hover:shadow-md transition-shadow. Form input: w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500. Avatar with fallback: object-cover w-12 h-12 rounded-full bg-gray-200.","source":"https://www.robinwieruch.de/react-hooks-fetch-data/","relevance":"medium","codeExample":"// Loading
