import { useState, useEffect } from 'react';
import type { User } from '../types/user';

export function useUsers() {
  const [users, setUsers] = useState<User[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [refreshKey, setRefreshKey] = useState(0);

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    setError(null);
    fetch('/api/users')
      .then(res => { if (!res.ok) throw new Error(`HTTP ${res.status}`); return res.json() as Promise<User[]>; })
      .then(data => { if (!cancelled) { setUsers(data); setLoading(false); } })
      .catch(err => { if (!cancelled) { setError(err.message); setLoading(false); } });
    return () => { cancelled = true; };
  }, [refreshKey]);

  const refresh = () => setRefreshKey(k => k + 1);
  return { users, loading, error, refresh };
}"},{"topic":"React 18 Form State Pattern (no external library)","summary":"Single form state object with computed handleChange using [e.target.name]. Separate submitting + formError states. handleSubmit: preventDefault, set submitting=true, fetch POST/PUT, throw on !res.ok, call onSuccess callback, catch sets formError, finally clears submitting. Inline validation before fetch call.","source":"https://www.robinwieruch.de/react-hooks-fetch-data/","relevance":"high","codeExample":"// src/components/UserForm.tsx
